// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        vm.deal(address(c), 1 ether);
        uint256 depositsBefore = c.depositsCount();

        // Call sendMoney — this may revert if target is address(0) or has no receive/fallback
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));

        uint256 depositsAfter = c.depositsCount();

        // The invariant: if sendMoney succeeded and value > 0, depositsCount increments by 1; otherwise it stays the same
        assertTrue(
            (success && value > 0 && depositsAfter == depositsBefore + 1) ||
            (!success || value == 0 && depositsAfter == depositsBefore)
        );
    }
}

