pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        vm.assume(_value > 0);
        vm.assume(_target != address(0));
        uint256 before = c.depositsCount();
        (bool success, ) = address(c).call{value: _value}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", _target, _value, _data));
        // The sendMoney call itself does not change depositsCount; only the fallback changes it.
        // The fallback is triggered by any ether sent to the contract.
        // But sendMoney sends _value to _target, not to the contract itself, so depositsCount stays unchanged.
        uint256 after = c.depositsCount();
        assertTrue(after == before);
    }
}

