pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint _value, bytes memory _data) public {
        // Bound value to prevent overflow and ensure reasonable amounts
        vm.assume(_target != address(0) && _target != address(c));
        _value = bound(_value, 0, address(this).balance);

        // Record initial balances
        uint initialOwnerBalance = c.owner().balance;
        uint initialContractBalance = address(c).balance;

        // Give contract some initial funds
        vm.deal(address(c), 1 ether);
        initialContractBalance = address(c).balance;

        // Send money from contract to target
        c.sendMoney(_target, _value, _data);

        // Rule: owner's balance + contract balance == initial owner balance + initial contract balance (no net change for owner)
        uint finalOwnerBalance = c.owner().balance;
        uint finalContractBalance = address(c).balance;
        assertTrue(finalOwnerBalance + finalContractBalance == initialOwnerBalance + initialContractBalance, "Balance invariance broken");
    }
}

