contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Record initial depositsCount
        uint initialDeposits = c.depositsCount();

        // Wrap sendMoney call to capture revert
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));

        // After the call, depositsCount should equal initialDeposits (no fallback was triggered because we sent 0 value)
        // If value > 0, the fallback would have been triggered, but we cannot assume that here
        // General rule: depositsCount never changes after a sendMoney call that sends 0 value
        if (value == 0) {
            assertTrue(c.depositsCount() == initialDeposits, "depositsCount changed without value transfer");
        }
    }
}

