pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Bound value to avoid excessive gas
        vm.assume(value <= 1 ether);
        // Record initial balances
        uint256 initialOwnerBalance = address(this).balance;
        uint256 initialContractBalance = address(c).balance;

        // Pre-fund contract if needed
        bool needFunding = value > 0;
        if (needFunding) {
            vm.deal(address(c), address(c).balance + value);
        }

        // Call sendMoney
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));

        // The general rule: contract balance should not increase by more than the value sent in
        // any single call; specifically for the reference, each sendMoney call sends value out,
        // so contract balance decreases by value (if success) or stays same (if revert)
        uint256 finalContractBalance = address(c).balance;
        uint256 finalOwnerBalance = address(this).balance;

        // Owner balance changes only via fallback (which sends ETH to this test contract)
        // This balance change only happens if call reverted? Actually fallback doesn't send ETH.
        // We use a simpler rule: after sendMoney, contract balance is at most initialContractBalance + value (if funding happened)
        // But more precisely: contract balance + value sent = initialContractBalance + value (if funded) - value transfers
        // Simpler: contract balance cannot exceed initialContractBalance + value (the max it could receive)
        assertTrue(finalContractBalance <= initialContractBalance + value);
    }
}

